{
  "name": "postman-profile-{{suffix}}",
  "description": "Fake harness profile created by Postman",
  "harnessType": "Generic",
  "executable": "garrison-fake-harness",
  "promptDelivery": "Stdin",
  "systemPromptDelivery": "PrependToPrompt",
  "mcpConfigFormat": "None",
  "outputParser": "ClaudeStreamJson",
  "resultSource": "ParserFinalEvent",
  "successPolicy": "FinalEvent",
  "defaultTimeoutSeconds": 120,
  "killGraceSeconds": 2,
  "isolateHome": true,
  "arguments": [
    {
      "template": "--format"
    },
    {
      "template": "claude"
    }
  ],
  "successExitCodes": [
    0
  ],
  "probeArguments": [
    "--version"
  ],
  "sessionFormat": "postman-session-v1"
}

{
  "name": "postman-node-skill-{{suffix}}",
  "kind": "Skill",
  "description": "Shipped to the Postman node with its lease",
  "tags": [
    "postman"
  ]
}

{
  "version": 2,
  "document": "apiVersion: garrison/v1
kind: Agent
metadata:
  name: postman-scratch-{{suffix}}
spec:
  displayName: Scratch
"
}

{
  "input": "Start a conversation from Postman",
  "startConversation": true,
  "wait": true,
  "waitSeconds": 60
}

{
  "input": "File space conversation from Postman",
  "startConversation": true,
  "wait": true,
  "waitSeconds": 60
}

{
  "name": "postman-pipeline-{{suffix}}",
  "description": "Two fake-harness stages with a review gate on the first",
  "stages": [
    {
      "name": "draft",
      "agentId": "{{agentId}}",
      "deploymentId": "{{deploymentId}}",
      "requiresReview": true,
      "maxRevisions": 1,
      "parameters": [
        {
          "name": "format",
          "value": "claude"
        }
      ]
    },
    {
      "name": "edit",
      "agentId": "{{agentId}}",
      "maxAttempts": 2,
      "outputCharLimit": 4000
    }
  ]
}

{
  "input": "Write release notes from Postman",
  "sampleOutputs": [
    "Sample draft from Postman"
  ]
}

{
  "nodeId": "{{nodeId}}",
  "epoch": {{leaseEpoch}},
  "events": [
    {
      "sequence": 1,
      "eventType": "Lifecycle",
      "timestampUtc": "{{$isoTimestamp}}",
      "text": "Started by Postman."
    },
    {
      "sequence": 2,
      "eventType": "AssistantText",
      "timestampUtc": "{{$isoTimestamp}}",
      "text": "Hello from the Postman node."
    },
    {
      "sequence": 3,
      "eventType": "Usage",
      "timestampUtc": "{{$isoTimestamp}}",
      "inputTokens": 5,
      "outputTokens": 6
    }
  ]
}

{
  "jsonrpc": "2.0",
  "id": 207,
  "method": "tools/call",
  "params": {
    "name": "garrison_apply_manifest",
    "arguments": {
      "tenantId": "{{tenantId}}",
      "manifest": "apiVersion: garrison/v1\nkind: Agent\nmetadata:\n  name: postman-mcp-dry-run\nspec:\n  description: Dry-run only.\n",
      "dryRun": true
    }
  }
}

{
  "agentId": "{{agentId}}",
  "name": "postman-dep-{{suffix}}",
  "harnessProfileId": "{{fakeProfileId}}",
  "parameters": [
    {
      "name": "format",
      "value": "claude"
    }
  ],
  "allowedRunOverrides": [
    {
      "name": "format",
      "validation": "Enum",
      "pattern": "claude,codex,mux"
    }
  ],
  "description": "Updated by Postman",
  "timeoutSeconds": 120,
  "approvalsEnabled": false,
  "approvalDefaultAction": "Deny",
  "approvalTimeoutSeconds": 120,
  "approvalTimeoutDecision": "Deny",
  "approvalRules": [
    {
      "action": "Allow",
      "pattern": "Bash(git status:*)",
      "description": "Read-only git status"
    },
    {
      "action": "Deny",
      "pattern": "Bash(rm:*)"
    }
  ]
}

{
  "name": "postman-keeper-{{suffix}}",
  "description": "Watches the Postman queue",
  "agentId": "{{agentId}}",
  "deploymentId": "{{deploymentId}}",
  "currentRevision": {
    "objective": "Keep the Postman queue short and say what changed.",
    "healthyDefinition": "Nothing waits longer than an hour.",
    "autonomy": "Close duplicates on its own.",
    "escalationPolicy": "Ask a person before deleting anything.",
    "signals": [
      {
        "name": "queue depth",
        "description": "Items waiting"
      }
    ],
    "wakeMode": "Backoff",
    "minIntervalSeconds": 10,
    "maxIntervalSeconds": 7200,
    "backoffFactor": 2,
    "budgetPerTickUsd": 0.5
  }
}

{
  "name": "postman-keeper-{{suffix}}",
  "description": "Watches the Postman queue and its backlog",
  "deploymentId": "{{deploymentId}}"
}

{
  "objective": "Keep the Postman queue under ten items.",
  "changeNote": "Tighter target",
  "wakeMode": "Fixed",
  "minIntervalSeconds": 600
}

{
  "targetKind": "Mandate",
  "targetId": "{{mandateId}}",
  "reason": "Postman: pause the keeper while the queue is investigated",
  "cancelActiveRuns": false
}

{
  "jsonrpc": "2.0",
  "id": 101,
  "method": "tools/call",
  "params": {
    "name": "garrison_memory_write",
    "arguments": {
      "tenantId": "{{tenantId}}",
      "agent": "{{agentName}}",
      "key": "postman/notes",
      "value": "Postman wrote this note. The queue drained at 02:00 UTC.",
      "category": "postman",
      "tags": [
        "postman",
        "notes"
      ]
    }
  }
}

{
  "agent": "{{agentName}}",
  "title": "Postman nightly import",
  "kind": "Status",
  "health": "Degraded",
  "audience": "Manager",
  "body": "Two of five feeds arrived late. The import finished at 02:40 UTC.",
  "metrics": [
    {
      "name": "rows",
      "value": 1200,
      "unit": "count"
    },
    {
      "name": "late_feeds",
      "value": 2
    }
  ],
  "issues": [
    {
      "severity": "Medium",
      "text": "Feed B arrives after the window."
    }
  ],
  "decisions": [
    {
      "text": "Retried feed B once."
    }
  ],
  "idempotencyKey": "{{reportKey}}"
}

{
  "agent": "{{agentName}}",
  "title": "Postman nightly import",
  "kind": "Status",
  "health": "Degraded",
  "audience": "Manager",
  "body": "Two of five feeds arrived late. The import finished at 02:40 UTC.",
  "metrics": [
    {
      "name": "rows",
      "value": 1200,
      "unit": "count"
    },
    {
      "name": "late_feeds",
      "value": 2
    }
  ],
  "issues": [
    {
      "severity": "Medium",
      "text": "Feed B arrives after the window."
    }
  ],
  "decisions": [
    {
      "text": "Retried feed B once."
    }
  ],
  "idempotencyKey": "{{reportKey}}"
}

{
  "jsonrpc": "2.0",
  "id": 111,
  "method": "tools/call",
  "params": {
    "name": "garrison_file_report",
    "arguments": {
      "tenantId": "{{tenantId}}",
      "agent": "{{agentName}}",
      "title": "Postman import failing",
      "kind": "Incident",
      "health": "Unhealthy",
      "issues": [
        {
          "severity": "High",
          "text": "The source database refuses connections."
        }
      ]
    }
  }
}

{
  "recipient": "{{agentName}}",
  "parentMessageId": "{{messageId}}",
  "subject": "Postman: also the prod keys",
  "body": "Prod after staging."
}

{
  "name": "postman-org-{{suffix}}",
  "description": "Organization created by Postman",
  "mission": "Keep the Postman fixtures healthy."
}

{
  "organizationId": "{{orgName}}",
  "unitId": "engineering",
  "name": "postman-rule-{{suffix}}",
  "description": "Prompt and wake tuning below engineering, created by Postman",
  "classes": [
    {
      "class": "PromptRetune"
    },
    {
      "class": "WakeTuning"
    }
  ],
  "limits": [
    {
      "class": "WakeTuning",
      "name": "minIntervalSeconds",
      "minimum": 300
    }
  ]
}

{
  "allow": false,
  "reason": "Postman: there is no such proposal."
}

{
  "name": "postman-ceo-{{suffix}}",
  "agentId": "{{agentId}}",
  "deploymentId": "{{deploymentId}}",
  "currentRevision": {
    "objective": "Run the Postman organization and brief the board.",
    "minIntervalSeconds": 3600,
    "briefIntervalHours": 24
  }
}

{
  "direction": "Hold spend flat until the Postman review is done.",
  "changeNote": "Postman direction"
}

{
  "input": "What is the state of the organization?"
}

{
  "name": "postman-inference-{{suffix}}",
  "kind": "BearerToken",
  "value": "postman-placeholder-token",
  "description": "Created by Postman for the inference endpoint examples"
}
